// Biblioteka kursów Bartka ze Skool: kursy → moduły → lekcje (wideo Loom/YouTube do osadzenia + link do lekcji na Skool).
// WYGENEROWANE skryptem materialy/skool/generuj-kursy.mjs (poza repo) z materialy/skool/struktura.json — nie edytuj ręcznie:
// zmień skrypt (tytuły, opisy, moduły) i uruchom go ponownie: node materialy/skool/generuj-kursy.mjs
// 179 lekcji, 159 z wideo, 20 bez wideo (tylko link „Otwórz na Skool”).
// Miniatura filmu: 159 lekcji, czas nagrania: 159 (Loom: oEmbed, YouTube: i.ytimg.com). Bez miniatury karta pokazuje okładkę zastępczą.
// Kolejność kursów, modułów i lekcji jak na Skool.
// id lekcji = "sk-" + 10 znaków parametru md z linku Skool: stałe, od nich zależy „obejrzane” (state.watched).
// Tytuły lekcji bez imion pracowników i nazwy studia; opisy krótkie, własnymi słowami. DO ZATWIERDZENIA (Bartek): tytuły i opisy.

export type LekcjaKursu = {
  id: string;
  title: string;
  course: string; // id kursu z KURSY
  module: string; // id modułu
  sekcja?: string; // część modułu (na Skool oddzielona separatorem), np. „Trener”
  video?: string; // adres odtwarzacza do osadzenia (Loom embed albo YouTube nocookie)
  thumb?: string; // miniatura filmu (Loom: oEmbed przy generowaniu, YouTube: i.ytimg.com)
  duration?: number; // czas nagrania w sekundach
  skool: string; // lekcja na Skool (zapasowy link „Otwórz na Skool”)
  attachments?: string[]; // nazwy materiałów do lekcji (pliki są na Skool)
  opis?: string; // 1 zdanie własnymi słowami
};

export type ModulKursu = { id: string; title: string; opis: string; lessons: IdLekcjiKursu[] };
export type Kurs = { id: string; title: string; opis: string; modules: ModulKursu[] };

