  "sk-f79ed2a44f": { id: "sk-f79ed2a44f", title: "Zarządzanie sobą: stwórz kodeks", course: "pt", module: "pt-start", video: "https://www.loom.com/embed/c5a8aaaead7b4172a92fcbb01b98f971", thumb: "https://cdn.loom.com/sessions/thumbnails/c5a8aaaead7b4172a92fcbb01b98f971-72fb6960d68c3094.jpg", duration: 340, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=f79ed2a44f6c4c0f9b54ba94c53acb5c", attachments: ["dokument"], opis: "Kilka zasad na co dzień: działać, nawet gdy nie jest idealnie, nie odkładać, myśleć jak właściciel, uczyć się sprzedaży i mierzyć wyniki liczbami. Najlepiej mieć je na widoku." },
  "sk-532ecf7f31": { id: "sk-532ecf7f31", title: "Mindset i rutyny", course: "pt", module: "pt-start", video: "https://www.loom.com/embed/5a2403e0a062458d9e9675df173bdfaa", thumb: "https://cdn.loom.com/sessions/thumbnails/5a2403e0a062458d9e9675df173bdfaa-694376da1d771ead.jpg", duration: 760, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=532ecf7f31ce40a4b488b218b02116cc", attachments: ["dokument"], opis: "Rytm dnia bez telefonu przed snem i zaraz po przebudzeniu, rano tworzenie zamiast reagowania, ruch bez uciekania w trening i proste nawyki wieczorne, które obniżają stres." },
  "sk-9120fca80c": { id: "sk-9120fca80c", title: "Wprowadzenie: kim jest trener", course: "pt", module: "pt-miekkie", video: "https://www.loom.com/embed/2fe78e3efa9042fea10780fef29c1f37", thumb: "https://cdn.loom.com/sessions/thumbnails/2fe78e3efa9042fea10780fef29c1f37-9517b0038a28f869.jpg", duration: 1119, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=9120fca80c854bd88e01f9f36e0bc011", attachments: ["dokument"], opis: "Technika to mała część pracy trenera. Reszta to relacja, atmosfera i własny przykład: kto dba o własny trening, sen i jedzenie, nie musi nikogo ciągnąć na siłę." },
  "sk-25093147cd": { id: "sk-25093147cd", title: "Budowanie relacji na treningu", course: "pt", module: "pt-miekkie", video: "https://www.loom.com/embed/005473088afd4af580c4889da36b7c75", thumb: "https://cdn.loom.com/sessions/thumbnails/005473088afd4af580c4889da36b7c75-c016455b50ee4848.jpg", duration: 393, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=25093147cdb74dcbbb4bda300fcffb79", attachments: ["dokument"], opis: "Ludzie wracają do ludzi, nie do ćwiczeń. Przywitanie z energią, pytania o życie klienta, czytanie jego nastroju, pełna obecność w najcięższej części treningu i krótka wiadomość następnego dnia." },
  "sk-718b3389e3": { id: "sk-718b3389e3", title: "Ustaw siebie, a ustawisz klienta", course: "pt", module: "pt-miekkie", video: "https://www.loom.com/embed/d2e5ad40ef1b4207879c382de1ba95d7", thumb: "https://cdn.loom.com/sessions/thumbnails/d2e5ad40ef1b4207879c382de1ba95d7-05714d2297bb58cd.jpg", duration: 882, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=718b3389e3934227abb380035dcece29", attachments: ["dokument"], opis: "Wygląd, punktualność, język i mowa ciała mówią klientowi, czy jest w dobrych rękach. Ekspert prowadzi według planu i spokojnie stawia granice, gdy klient się spóźnia albo ma własne pomysły." },
  "sk-335221029e": { id: "sk-335221029e", title: "Narzędzia trenera: wprowadzenie", course: "pt", module: "pt-twarde", video: "https://www.loom.com/embed/2c2e87bd203a4ad295ea4279858f9ed4", thumb: "https://cdn.loom.com/sessions/thumbnails/2c2e87bd203a4ad295ea4279858f9ed4-b5bedddd85551175.jpg", duration: 134, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=335221029e434312a01570fcc7b7667f" },
  "sk-80fa7268b4": { id: "sk-80fa7268b4", title: "Lista niezbędnych narzędzi", course: "pt", module: "pt-twarde", video: "https://www.loom.com/embed/b8154ac7b2bb485d89e90b48c99a8a16", thumb: "https://cdn.loom.com/sessions/thumbnails/b8154ac7b2bb485d89e90b48c99a8a16-89dbe58b5590fc2e.jpg", duration: 327, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=80fa7268b44f48ae8382cc1f65618022" },
