  "sk-4656de5deb": { id: "sk-4656de5deb", title: "Linktree: stwórz swój", course: "pt", module: "pt-twarde", video: "https://www.loom.com/embed/b935a37348d44d53a65ca7edd7745ed0", thumb: "https://cdn.loom.com/sessions/thumbnails/b935a37348d44d53a65ca7edd7745ed0-3920a6cd0fbd04ca.jpg", duration: 550, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=4656de5debe44792a86af4ea71b6edb9" },
  "sk-23ffe77786": { id: "sk-23ffe77786", title: "Wprowadzenie", course: "pt", module: "pt-merytoryka", video: "https://www.loom.com/embed/8875da1ac0e04746a80a35e9ce235d24", thumb: "https://cdn.loom.com/sessions/thumbnails/8875da1ac0e04746a80a35e9ce235d24-31700fe4610990a7.jpg", duration: 185, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=23ffe777863545e393de6c2a1ffd194b", attachments: ["dokument"] },
  "sk-92c4b31b32": { id: "sk-92c4b31b32", title: "Czym jest trening personalny?", course: "pt", module: "pt-merytoryka", video: "https://www.loom.com/embed/f20ea9368fb245f5a31eb0fbf5c36895", thumb: "https://cdn.loom.com/sessions/thumbnails/f20ea9368fb245f5a31eb0fbf5c36895-56e3c31a972364e3.jpg", duration: 281, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=92c4b31b32fb4527b9f02d98900e0b2b", attachments: ["dokument"], opis: "U początkujących o efekcie decyduje głównie to, czy klient polubił trenera i atmosferę oraz czy zaangażował się finansowo. Wiedza jest fundamentem, ale studio potrzebuje i metodyki, i pracy nad relacją." },
  "sk-20ebf79634": { id: "sk-20ebf79634", title: "Metodyka treningu personalnego", course: "pt", module: "pt-merytoryka", video: "https://www.loom.com/embed/5788faf5a3c2466a995a44c719f9ea23", thumb: "https://cdn.loom.com/sessions/thumbnails/5788faf5a3c2466a995a44c719f9ea23-0d2ba0ed138354f4.jpg", duration: 1040, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=20ebf79634bc4f7c9d5fd6b0d8e091c2", attachments: ["dokument"], opis: "Stały schemat jednostki: rozgrzewka, mobilizacja, część główna na cztery części ciała, ćwiczenia dodatkowe pod cel klienta i interwał. Nowa osoba najpierw uczy się wzorców ruchu z zapasem siły w każdej serii." },
  "sk-4daa4cb36e": { id: "sk-4daa4cb36e", title: "Śledzenie postępów klienta", course: "pt", module: "pt-merytoryka", video: "https://www.loom.com/embed/c62b498a41da46138632e2341c9f12ee", thumb: "https://cdn.loom.com/sessions/thumbnails/c62b498a41da46138632e2341c9f12ee-77fc09bb8f5f5654.jpg", duration: 466, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=4daa4cb36edd434aab75463b5a6ab9c8", attachments: ["dokument"], opis: "Prosty szablon planu i notatki z treningów wystarczą, żeby każdy trener w zespole wiedział, gdzie klient był miesiąc temu i dokąd zmierza." },
  "sk-609d7d1ff6": { id: "sk-609d7d1ff6", title: "Fakty i mity", course: "pt", module: "pt-merytoryka", video: "https://www.loom.com/embed/e55ede0871d54346820e773e094a3341", thumb: "https://cdn.loom.com/sessions/thumbnails/e55ede0871d54346820e773e094a3341-2a23a3ae28d484b5.jpg", duration: 232, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=609d7d1ff6514467bc764fe6249f43c4", attachments: ["dokument"], opis: "To, że waga stoi, nie znaczy, że klient nie ma efektów. Najważniejsze zmiany często dzieją się w śnie, samopoczuciu i głowie, a dobry trening to czasem mniej stresu, nie więcej ciężaru." },
  "sk-e6f51fe76e": { id: "sk-e6f51fe76e", title: "Praca domowa", course: "pt", module: "pt-merytoryka", video: "https://www.loom.com/embed/5045b6e2addf40a09b0f41660b17fdd4", thumb: "https://cdn.loom.com/sessions/thumbnails/5045b6e2addf40a09b0f41660b17fdd4-00c973abe9110410.jpg", duration: 129, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=e6f51fe76ebf4779bb3b5b04485dfc95", attachments: ["dokument"], opis: "Bez spisanej metodyki każdy trener prowadzi po swojemu, a klient dostaje inną usługę u każdego." },
  "sk-abcb364e6e": { id: "sk-abcb364e6e", title: "Wprowadzenie", course: "pt", module: "pt-oferta", video: "https://www.loom.com/embed/86e5eb7020164145adc6e05fda087dd6", thumb: "https://cdn.loom.com/sessions/thumbnails/86e5eb7020164145adc6e05fda087dd6-cbc49bdc1c253bc1.jpg", duration: 363, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=abcb364e6e104b609d36b65a75fe9319", attachments: ["dokument"] },
