  "sk-6b18b3c733": { id: "sk-6b18b3c733", title: "Jak robić świetne relacje (stories)?", course: "pt", module: "pt-oferta", video: "https://www.loom.com/embed/7635c577b83a4ba4a5be889cb19acd7d", thumb: "https://cdn.loom.com/sessions/thumbnails/7635c577b83a4ba4a5be889cb19acd7d-fba1c925b08b5972.jpg", duration: 1627, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=6b18b3c7335c46a9b97e7e3cd1008c02", attachments: ["dokument"] },
  "sk-c2748f53bd": { id: "sk-c2748f53bd", title: "Budowanie społeczności", course: "pt", module: "pt-spolecznosc", video: "https://www.loom.com/embed/31dadb4038074de6a3c5686018ddaa37", thumb: "https://cdn.loom.com/sessions/thumbnails/31dadb4038074de6a3c5686018ddaa37-1bc835ea44b63358.jpg", duration: 1634, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=c2748f53bd6e41fea1661488c73c904b", attachments: ["dokument"] },
  "sk-23bd68706a": { id: "sk-23bd68706a", title: "Wideo powitalne na grupie", course: "pt", module: "pt-spolecznosc", video: "https://www.loom.com/embed/7fba5aa61d644f90a5b10b3fef3cf1c9", thumb: "https://cdn.loom.com/sessions/thumbnails/7fba5aa61d644f90a5b10b3fef3cf1c9-39c51ce2fa891613.jpg", duration: 230, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=23bd68706a2c4a7fa83bbbaba5548250", attachments: ["dokument"], opis: "Co powiedzieć w krótkim filmie powitalnym dla nowego klienta i co przypiąć w grupie." },
