  "sk-3cc7a90977": { id: "sk-3cc7a90977", title: "Ultraważne: obsługa klienta i sprzedaż, zasady", course: "pt", module: "pt-sprzedaz", video: "https://www.loom.com/embed/beca19ace50349dfaa156fe44a65b627", thumb: "https://cdn.loom.com/sessions/thumbnails/beca19ace50349dfaa156fe44a65b627-fbe01525a601fc5c.jpg", duration: 5080, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=3cc7a90977004199b83b2db507a43f10", attachments: ["ebook"], opis: "Zasady obsługi klienta i sprzedaży, od których zależy, czy zgłoszenie zamieni się w klienta. Do lekcji jest e-book." },
