  "sk-48fcda0239": { id: "sk-48fcda0239", title: "Wdrożenie modelu biznesowego, cz. 2", course: "pt", module: "pt-semi", video: "https://www.loom.com/embed/18af4bd95c2f4c3483151c8fe0f10110", thumb: "https://cdn.loom.com/sessions/thumbnails/18af4bd95c2f4c3483151c8fe0f10110-4f4ed859d033d688.jpg", duration: 349, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=48fcda0239fe431789b13cae7c126fd0", attachments: ["dokument"], opis: "Dalsza część wdrożenia modelu. Dla ostrożnych wariant łagodny: nowe zasady tylko dla nowych osób." },
