  "sk-f3c32335eb": { id: "sk-f3c32335eb", title: "Fakty i mity (mindset)", course: "pt", module: "pt-semi", video: "https://www.loom.com/embed/a1b0988b1fd84c709e39a67330d5a736", thumb: "https://cdn.loom.com/sessions/thumbnails/a1b0988b1fd84c709e39a67330d5a736-db77dfb12a9a5dfa.jpg", duration: 404, skool: "https://www.skool.com/dochodowestudio/classroom/f26e69ea?md=f3c32335eb7d491288f261274f86b1ca", attachments: ["dokument"], opis: "Najczęstsze obawy: że klient nie zapłaci tyle samo, że nie da się ogarnąć kilku osób, że spadnie jakość. Chaos to brak systemu, a nie liczba osób na sali." },
