export const WSZYSTKIE_LEKCJE: LekcjaKursu[] = Object.values(LEKCJE);

export function kursLekcji(l: LekcjaKursu): Kurs | undefined {
  return KURSY.find((k) => k.id === l.course);
}

export function modulLekcji(l: LekcjaKursu): ModulKursu | undefined {
  return kursLekcji(l)?.modules.find((m) => m.id === l.module);
}

/** Lekcje modułu po kolei (id modułu z KURSY, np. "pt-miekkie"). */
export function lekcjeModulu(modulId: string): LekcjaKursu[] {
  for (const k of KURSY) {
    const m = k.modules.find((x) => x.id === modulId);
    if (m) return m.lessons.map((id) => LEKCJE[id]);
  }
  return [];
}

/** Miniatura filmu: zapisana przy generowaniu albo (YouTube) wyliczona z adresu do osadzenia. */
export function miniatura(l: { thumb?: string; video?: string }): string | undefined {
  if (l.thumb) return l.thumb;
  const yt = l.video?.match(/youtube(?:-nocookie)?\.com\/embed\/([\w-]{11})/)?.[1];
  return yt ? `https://i.ytimg.com/vi/${yt}/hqdefault.jpg` : undefined;
}

/** Miniatura i czas filmu dla dowolnej lekcji (także lekcji kroku ścieżki, która wskazuje lekcję kursu polem ref). */
export function wideoLekcji(l: { ref?: string; thumb?: string; duration?: number; video?: string }): { thumb?: string; duration?: number } {
  const k = l.ref ? (LEKCJE as Record<string, LekcjaKursu | undefined>)[l.ref] : undefined;
  return { thumb: l.thumb ?? (k ? miniatura(k) : undefined) ?? miniatura(l), duration: l.duration ?? k?.duration };
}

/** „Skool · <kurs> · <moduł>” — źródło lekcji w ścieżce. */
export function zrodlo(l: LekcjaKursu): string {
  return `Skool · ${kursLekcji(l)?.title ?? ""} · ${modulLekcji(l)?.title ?? ""}`;
}
